package openapidoc

import "encoding/json"

const workflowTemplatesDescription = "Templates loads the built-in list. The request sends no filter. The list is every workflow you can start from."

const workflowTemplatesJSON = `{"templates":[{"slug":"relationship-refresh","taskSlug":"oppulence-relationship-refresh","name":"Relationship Refresh","description":"Continuously summarize relationship state, evidence freshness, commitments, and material changes.","instructions":"Use relationship.read with view=portfolio and run_history.read. Compare current versioned relationship state with the prior run, identify only material changes, cite relationship and evidence references returned by the tool, and write a concise markdown portfolio refresh. Never invent evidence or execute an external action.","active":true,"triggers":{"cronExpr":"*/15 * * * *","timezone":"UTC"},"executionTarget":"api","tags":["first-party","relationships","evidence","scheduled"],"version":1,"firstParty":true},{"slug":"attention-monitor","taskSlug":"oppulence-attention-monitor","name":"Attention Monitor","description":"Explain which relationships need attention now and why.","instructions":"Use relationship.read with view=attention and run_history.read. Rank open attention items by urgency and score, explain the deterministic reason and freshness, cite every triggering object and evidence reference, and write an operator-ready markdown brief. Recommend review actions only; do not perform external actions.","active":true,"triggers":{"cronExpr":"0 8 * * *","timezone":"America/New_York"},"executionTarget":"api","tags":["first-party","attention","risk","scheduled"],"version":1,"firstParty":true},{"slug":"meeting-pre-brief","taskSlug":"oppulence-meeting-pre-brief","name":"Meeting Pre-Brief","description":"Prepare evidence-linked context, commitments, risks, and goals for upcoming customer meetings.","instructions":"Use connector.read.calendar for upcoming meetings, relationship.read with view=portfolio for matching customer context, and run_history.read. For meetings in the next 24 hours, write a concise brief with participants, relationship health, open commitments, risks, last material change, desired outcome, and evidence references. If no relevant meeting exists, record that clearly. Do not contact participants.","active":true,"triggers":{"cronExpr":"*/30 * * * *","timezone":"UTC"},"executionTarget":"api","tags":["first-party","meeting","brief","scheduled"],"requiredConnectors":["google"],"version":1,"firstParty":true},{"slug":"post-meeting-processor","taskSlug":"oppulence-post-meeting-processor","name":"Post-Meeting Processor","description":"Turn completed meetings and transcripts into evidence-linked commitments, risks, and approval-ready follow-ups.","instructions":"Use event.read when event-triggered, connector.read.calendar for recently completed meetings, relationship.read with view=portfolio, and run_history.read. Produce a markdown meeting record containing decisions, commitments with owners and dates, risks, unresolved questions, relationship changes, and draft follow-up recommendations. Cite source references. Any outward action must remain a proposal requiring human approval.","active":true,"triggers":{"cronExpr":"*/15 * * * *","timezone":"UTC","events":{"sources":["google"],"eventTypes":["resource.exists","resource.update"]}},"executionTarget":"api","tags":["first-party","meeting","transcript","event","scheduled"],"requiredConnectors":["google"],"version":1,"firstParty":true},{"slug":"recommendation-review","taskSlug":"oppulence-recommendation-review","name":"Recommendation Review","description":"Assemble pending recommendations into a transparent, approval-ready review queue.","instructions":"Use relationship.read with view=recommendations and run_history.read. Group pending recommendations by relationship, show priority, reason, revision, policy and approval state, flag stale or conflicting evidence, and write a review brief. Never approve, reject, or execute on the user's behalf.","active":true,"triggers":{"cronExpr":"0 9 * * 1-5","timezone":"America/New_York"},"executionTarget":"api","tags":["first-party","recommendations","approval","scheduled"],"version":1,"firstParty":true},{"slug":"connector-health-repair","taskSlug":"oppulence-connector-health-repair","name":"Connector Health and Repair","description":"Monitor source freshness, scopes, retries, and backfill progress with actionable repair guidance.","instructions":"Use relationship.read with view=sources and run_history.read. Report each connector's authorization, freshness, completeness, missing scopes, retry state, lag, and backfill progress. Separate transient retries from reconnect-required failures and write safe operator repair steps. Never request or expose secrets and never reconnect a provider automatically.","active":true,"triggers":{"cronExpr":"*/30 * * * *","timezone":"UTC","events":{"sources":["google","slack","hubspot"],"eventTypes":["*"]}},"executionTarget":"api","tags":["first-party","connectors","health","repair","scheduled"],"requiredConnectors":["google","slack","hubspot"],"version":1,"firstParty":true},{"slug":"inbox-digest","taskSlug":"inbox-digest","name":"Inbox Digest","description":"Summarize new priority email and produce a short follow-up plan.","instructions":"Review recent important Gmail messages, group them by account or topic, call out deadlines and blockers, and produce a markdown digest with concrete next actions.","active":true,"triggers":{"cronExpr":"0 8 * * 1-5","timezone":"America/New_York"},"model":"anthropic/claude-sonnet-4-5","provider":"openrouter","executionTarget":"api","tags":["gmail","digest","scheduled"],"requiredConnectors":["google"],"version":1,"firstParty":false},{"slug":"calendar-followups","taskSlug":"calendar-followups","name":"Calendar Follow-ups","description":"Turn recent meetings into follow-up notes, owners, and next steps.","instructions":"Inspect recent Google Calendar events and available notes, identify promised follow-ups, draft concise owner/action/deadline bullets, and highlight unresolved decisions.","active":true,"triggers":{"cronExpr":"0 17 * * 1-5","timezone":"America/New_York"},"model":"anthropic/claude-sonnet-4-5","provider":"openrouter","executionTarget":"api","tags":["calendar","follow-up","scheduled"],"requiredConnectors":["google"],"version":1,"firstParty":false},{"slug":"event-triage","taskSlug":"event-triage","name":"Event Triage","description":"Route inbound provider/webhook events into an actionable incident or support digest.","instructions":"For trigger=event runs, summarize the event payload, identify affected customers or systems, rate urgency, and recommend the next response. Include links or external ids when present.","active":true,"triggers":{"events":{"sources":["github","linear","stripe","webhook"],"eventTypes":["*"]}},"model":"anthropic/claude-sonnet-4-5","provider":"openrouter","executionTarget":"api","tags":["event","webhook","triage"],"version":1,"firstParty":false},{"slug":"data-report","taskSlug":"data-report","name":"Data Report","description":"Run sandboxed analysis and publish a markdown report.","instructions":"Use sandbox.run for bounded code or data analysis when needed. Generate a concise markdown report with inputs, method, key findings, and any attached artifact references.","active":true,"triggers":{"manual":true},"model":"anthropic/claude-sonnet-4-5","provider":"openrouter","executionTarget":"api","tags":["sandbox","report","manual"],"version":1,"firstParty":false}]}`

func workflowTemplatesPage() obj {
	var page obj
	if err := json.Unmarshal([]byte(workflowTemplatesJSON), &page); err != nil {
		panic(err)
	}
	return page
}
